NameIdx new_idx(int64_t n) {
    int64_t cap = 16;
    while (cap < (n * 2)) {
        cap = (cap * 2);
    }
    Array head = ({ Array _a = arr_make(sizeof(int64_t)); _a; });
    for (int64_t i = 0; i < cap; i++) {
        ({ int64_t _e = 0; arr_push(&(head), &_e); });
    }
    Array next = ({ Array _a = arr_make(sizeof(int64_t)); _a; });
    return (NameIdx){head, next, (cap - 1)};
}

int64_t name_hash(const char* s, int64_t mask) {
    uint64_t h = 5381;
    int64_t n = str_len(s);
    for (int64_t i = 0; i < n; i++) {
        h = ((h * 33) + ((uint64_t)(((uint8_t)(s[i])))));
    }
    return ((int64_t)((h & ((uint64_t)(mask)))));
}

void idx_add(NameIdx* x, const char* key, int64_t k) {
    int64_t b = name_hash(key, x->mask);
    ({ int64_t _e = ((int64_t*)(x->head).data)[b]; arr_push(&(x->next), &_e); });
    ((int64_t*)(x->head).data)[b] = (k + 1);
}

