const char* paren_cond(const char* c) {
    int64_t n = str_len(c);
    if (((n < 2) || (c[0] != '(')) || (c[(n - 1)] != ')')) {
        return str_concat(str_concat("(", c), ")");
    }
    int64_t depth = 0;
    int64_t i = 0;
    bool wraps = true;
    while ((i < (n - 1)) && wraps) {
        char ch = c[i];
        if ((ch == '"') || (ch == '\'')) {
            i += 1;
            while ((i < (n - 1)) && (c[i] != ch)) {
                if (c[i] == '\\') {
                    i += 1;
                }
                i += 1;
            }
        } else 
        if (ch == '(') {
            depth += 1;
        } else 
        if (ch == ')') {
            depth -= 1;
            if (depth == 0) {
                wraps = false;
            }
        }
        i += 1;
    }
    if (wraps) {
        return c;
    }
    return str_concat(str_concat("(", c), ")");
}

