int64_t prim_ty(const char* n) {
    if (str_eq(n, "int") || str_eq(n, "i64")) {
        return KI64;
    }
    if (str_eq(n, "i32")) {
        return KI32;
    }
    if (str_eq(n, "i16")) {
        return KI16;
    }
    if (str_eq(n, "i8")) {
        return KI8;
    }
    if (str_eq(n, "uint") || str_eq(n, "u64")) {
        return KU64;
    }
    if (str_eq(n, "u32")) {
        return KU32;
    }
    if (str_eq(n, "u16")) {
        return KU16;
    }
    if (str_eq(n, "u8") || str_eq(n, "bool")) {
        return KU8;
    }
    if (str_eq(n, "char")) {
        return KI8;
    }
    if (str_eq(n, "float") || str_eq(n, "f32")) {
        return KF32;
    }
    if (str_eq(n, "f64")) {
        return KF64;
    }
    if (str_eq(n, "string")) {
        return KU64;
    }
    return (0 - 1);
}

