int64_t digit_val(char c) {
    if ((c >= '0') && (c <= '9')) {
        return (((int64_t)(c)) - ((int64_t)('0')));
    }
    if ((c >= 'a') && (c <= 'f')) {
        return ((((int64_t)(c)) - ((int64_t)('a'))) + 10);
    }
    if ((c >= 'A') && (c <= 'F')) {
        return ((((int64_t)(c)) - ((int64_t)('A'))) + 10);
    }
    return 0;
}

int64_t parse_int(const char* s) {
    uint64_t v = 0;
    uint64_t base = 10;
    int64_t i = 0;
    int64_t n = str_len(s);
    if (((n > 2) && (s[0] == '0')) && ((s[1] == 'x') || (s[1] == 'X'))) {
        base = 16;
        i = 2;
    } else 
    if (((n > 2) && (s[0] == '0')) && ((s[1] == 'b') || (s[1] == 'B'))) {
        base = 2;
        i = 2;
    }
    while (i < n) {
        if (s[i] != '_') {
            v = ((v * base) + ((uint64_t)(digit_val(s[i]))));
        }
        i += 1;
    }
    return ((int64_t)(v));
}

int64_t char_val(const char* s) {
    if (str_len(s) == 0) {
        return 0;
    }
    if ((s[0] != '\\') || (str_len(s) < 2)) {
        return ((int64_t)(s[0]));
    }
    char e = s[1];
    if (e == 'n') {
        return 10;
    }
    if (e == 't') {
        return 9;
    }
    if (e == 'r') {
        return 13;
    }
    if (e == '0') {
        return 0;
    }
    return ((int64_t)(e));
}

