bool ends_with(const char* s, const char* suffix) {
    return ((str_len(s) >= str_len(suffix)) && str_eq(str_sub(s, (str_len(s) - str_len(suffix)), str_len(suffix)), suffix));
}

Project no_project(void) {
    Array e = ({ Array _a = arr_make(sizeof(const char*)); _a; });
    return (Project){false, "", "", "", "", "", "", "", false, e, e, e, e, e, e, false};
}

Target resolve_target(const char* arg) {
    if (ends_with(arg, ".strata") || ends_with(arg, ".str")) {
        return (Target){true, false, arg, no_project()};
    }
    const char* toml = "strata.toml";
    if (ends_with(arg, "strata.toml")) {
        toml = arg;
    } else 
    if (!str_eq(arg, "")) {
        toml = str_concat(arg, "/strata.toml");
    }
    if (!file_present(toml)) {
        if (str_eq(arg, "")) {
            strata_report("error: no strata.toml in this folder (pass a .strata file or a project folder, or create one with 'stratac new <name>')");
        } else {
            strata_report(str_concat("error: no strata.toml in ", arg));
        }
        return (Target){false, false, "", no_project()};
    }
    Project p = load_project(toml);
    return (Target){p.ok, true, str_concat(str_concat(p.root, "/"), p.entry), p};
}

BuildSpec target_spec(Target t, const char* version, bool release, bool force, bool quiet) {
    if (t.is_project) {
        return spec_for_project(t.proj, version, release, force, quiet);
    }
    return spec_for_file(t.file, version, quiet);
}

const char* stratac_version(void) {
    return "2.2.0 (runtime in Strata)";
}

bool file_exists(const char* p) {
    return (str_len(strata_read_file(p)) > 0);
}

const char* resolve_libdir(const char* argv0) {
    const char* exe = strata_exe_path();
    if (!str_eq(exe, "")) {
        const char* edir = dirname_of(exe);
        if (file_exists(str_concat(edir, "/lib/arena.h"))) {
            return str_concat(edir, "/lib");
        }
        if (file_exists(str_concat(edir, "/../lib/arena.h"))) {
            return str_concat(edir, "/../lib");
        }
    }
    const char* dir = dirname_of(argv0);
    if (file_exists(str_concat(dir, "/lib/arena.h"))) {
        return str_concat(dir, "/lib");
    }
    if (file_exists(str_concat(dir, "/../lib/arena.h"))) {
        return str_concat(dir, "/../lib");
    }
    if (file_exists("lib/arena.h")) {
        return "lib";
    }
    if (file_exists("../lib/arena.h")) {
        return "../lib";
    }
    return str_concat(dir, "/lib");
}

int64_t cmd_tokens(const char* path) {
    print_tokens(lex(strata_read_file(path)));
    return 0;
}

int64_t cmd_ast(const char* path) {
    Parser p = new_parser(lex(strata_read_file(path)));
    Program prog = parse_program((&p));
    if (p.had_error) {
        printf("%s\n", str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(basename_of(path), ":"), str_from_int(p.err_line)), ":"), str_from_int(p.err_col)), ": parse error: "), p.err_msg));
        return 1;
    }
    print_program(prog);
    return 0;
}

int64_t cmd_check(const char* path) {
    LoadResult lr = load_program(path);
    if (!lr.ok) {
        return 1;
    }
    Program prog = lr.prog;
    Checker* ck = new_checker(basename_of(path));
    ck_check(ck, prog);
    if (ck->had_error) {
        return 1;
    }
    printf("%s\n", "no type errors");
    return 0;
}

int64_t cmd_emit(const char* path) {
    LoadResult lr = load_program(path);
    if (!lr.ok) {
        return 1;
    }
    Program prog = lr.prog;
    Checker* ck = new_checker(basename_of(path));
    ck_check(ck, prog);
    if (ck->had_error) {
        return 1;
    }
    Codegen cg = new_codegen();
    const char* out = generate((&cg), prog);
    if (cg.had_error) {
        printf("%s\n", "codegen: program uses features not supported yet");
        return 1;
    }
    printf(("%s"), (out));
    return 0;
}

int64_t cmd_native(const char* path, bool show_ir, bool opt) {
    LoadResult lr = load_program(path);
    if (!lr.ok) {
        return 1;
    }
    Program prog = lr.prog;
    Checker* ck = new_checker(basename_of(path));
    ck_check(ck, prog);
    if (ck->had_error) {
        return 1;
    }
    NativeResult nr = native_compile(prog, true, opt);
    if (!nr.ok) {
        printf("%s\n", str_concat(str_concat(basename_of(path), ": error: can't compile natively: "), nr.why));
        return 1;
    }
    if (show_ir) {
        printf(("%s"), (nr.ir));
    } else {
        printf(("%s"), (nr.asm_text));
    }
    return 0;
}

int64_t cmd_assemble(const char* path, const char* out) {
    const char* src = strata_read_file(path);
    if (str_len(src) == 0) {
        printf("%s\n", str_concat("error: cannot read ", path));
        return 1;
    }
    ObjFile ob = assemble_x64(src);
    if (!ob.ok) {
        printf("%s\n", str_concat(str_concat(basename_of(path), ": error: "), ob.err));
        return 1;
    }
    if (str_eq(out, "")) {
        out = str_concat(stem_of(path), ".o");
    }
    if (!write_coff(out, (&ob))) {
        printf("%s\n", str_concat("error: cannot write ", out));
        return 1;
    }
    return 0;
}

int64_t cmd_object(const char* path, const char* out) {
    LoadResult lr = load_program(path);
    if (!lr.ok) {
        return 1;
    }
    Program prog = lr.prog;
    Checker* ck = new_checker(basename_of(path));
    ck_check(ck, prog);
    if (ck->had_error) {
        return 1;
    }
    if (prog.main.len > 0) {
        Stmt* st = ((Stmt**)(prog.main).data)[0];
        printf("%s\n", str_concat(str_concat(str_concat(str_concat(str_concat(basename_of(path), ":"), str_from_int(st->line)), ":"), str_from_int(st->col)), ": error: an object file has no main, so its file can't contain top-level code"));
        return 1;
    }
    NativeResult nr = native_compile(prog, false, true);
    if (!nr.ok) {
        printf("%s\n", str_concat(str_concat(basename_of(path), ": error: can't compile natively: "), nr.why));
        return 1;
    }
    ObjFile ob = assemble_x64(nr.asm_text);
    if (!ob.ok) {
        printf("%s\n", str_concat(str_concat(basename_of(path), ": internal error in the assembler: "), ob.err));
        return 1;
    }
    if (str_eq(out, "")) {
        out = str_concat(stem_of(path), ".o");
    }
    if (!write_coff(out, (&ob))) {
        printf("%s\n", str_concat("error: cannot write ", out));
        return 1;
    }
    return 0;
}

BuildSpec cli_spec(Target t, bool release, bool force, bool quiet, const char* backend) {
    BuildSpec s = target_spec(t, stratac_version(), release, force, quiet);
    s.backend = backend;
    return s;
}

int64_t cmd_build(Target t, const char* libdir, bool release, bool force, const char* backend) {
    if (run_build(cli_spec(t, release, force, false, backend), libdir)) {
        return 0;
    }
    return 1;
}

int64_t cmd_run(Target t, const char* libdir, bool release, bool force, const char* backend, Array prog_args) {
    BuildSpec spec = cli_spec(t, release, force, true, backend);
    if (spec.dll) {
        printf("%s\n", "error: this project builds a dll; there's nothing to run");
        return 1;
    }
    if (!run_build(spec, libdir)) {
        return 1;
    }
    const char* exe = spec.out_bin;
    if (str_eq(dirname_of(exe), ".")) {
        exe = str_concat("./", exe);
    }
    if (str_eq(host_os(), "windows")) {
        exe = win_path(exe);
    }
    Array argv = ({ Array _a = arr_make(sizeof(const char*)); _a; });
    ({ const char* _e = exe; arr_push(&(argv), &_e); });
    for (int64_t i = 0; i < prog_args.len; i++) {
        ({ const char* _e = ((const char**)(prog_args).data)[i]; arr_push(&(argv), &_e); });
    }
    return strata_run_argv((&argv));
}

int64_t cmd_new(const char* name) {
    if (file_exists(str_concat(name, "/strata.toml"))) {
        printf("%s\n", str_concat(str_concat("error: ", name), "/strata.toml already exists"));
        return 1;
    }
    if (!strata_make_dirs(str_concat(name, "/src"))) {
        printf("%s\n", str_concat(str_concat("error: could not create ", name), "/src"));
        return 1;
    }
    const char* pname = basename_of(name);
    const char* toml = str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat(str_concat("# ", pname), " - a Strata project. Build: stratac build   Run: stratac run\n"), "[project]\n"), "name    = \""), pname), "\"\n"), "version = \"0.1.0\"\n"), "entry   = \"src/main.strata\"\n"), "output  = \"exe\"          # or \"dll\"\n"), "\n"), "[build]\n"), "libs = []                # C libraries for every platform, e.g. [\"raylib\"]\n"), "\n"), "[windows]\n"), "libs = []                # e.g. [\"user32\"]\n"), "\n"), "[linux]\n"), "libs = []                # e.g. [\"X11\"]\n"), "\n"), "[macos]\n"), "frameworks = []          # e.g. [\"Cocoa\"]\n");
    bool ok = strata_write_file(str_concat(name, "/strata.toml"), toml);
    ok = (ok && strata_write_file(str_concat(name, "/src/main.strata"), str_concat(str_concat(str_concat(str_concat("// ", pname), " - the entry point. Other files in this folder are modules: `import name`.\nprint(\"hello from "), pname), "\")\n")));
    ok = (ok && strata_write_file(str_concat(name, "/.gitignore"), "build/\n"));
    if (!ok) {
        printf("%s\n", str_concat("error: could not write the project files in ", name));
        return 1;
    }
    printf("%s\n", str_concat(str_concat(str_concat(str_concat("created ", name), "/strata.toml and "), name), "/src/main.strata"));
    printf("%s\n", str_concat(str_concat("next:  cd ", name), "  then  stratac run"));
    return 0;
}

int64_t usage(void) {
    printf("%s\n", "stratac - the Strata compiler");
    printf("%s\n", "usage:");
    printf("%s\n", "  stratac new    <name>            create a project (strata.toml + src/main.strata)");
    printf("%s\n", "  stratac run    [target] [--release] [--force] [--backend b] [-- args]   build and run");
    printf("%s\n", "  stratac build  [target] [--release] [--force] [--backend b]             build an exe or dll");
    printf("%s\n", "  stratac check  [target]          type-check only");
    printf("%s\n", "  stratac emit   [target]          print the generated C");
    printf("%s\n", "  stratac asm    [target] [--release]   print the generated assembly (native backend)");
    printf("%s\n", "  stratac ir     [target] [--release]   print the native backend's IR");
    printf("%s\n", "  stratac assemble <file.s> [out.o]     assemble x86-64 (AT&T) into an object file");
    printf("%s\n", "  stratac object <file.strata> [out.o]  compile a module (no main) into an object file");
    printf("%s\n", "  stratac ast    <file.strata>     parse and print the AST");
    printf("%s\n", "  stratac tokens <file.strata>     print the token stream");
    printf("%s\n", "");
    printf("%s\n", "target: a .strata file, a project folder, a strata.toml, or nothing (the project");
    printf("%s\n", "in the current folder). Projects are cached: unchanged builds skip the C compiler.");
    printf("%s\n", "");
    printf("%s\n", "backend: native (Strata's own x86-64 code; --release optimizes it), c (C, then gcc),");
    printf("%s\n", "or auto (the default: native when it can build the program, else c).");
    return 2;
}

int64_t dmm_main(Array args) {
    if ((args.len == 2) && (str_eq(((const char**)(args).data)[1], "version") || str_eq(((const char**)(args).data)[1], "--version"))) {
        printf("%s\n", str_concat(str_concat("stratac ", stratac_version()), " - the Strata compiler"));
        return 0;
    }
    if (args.len < 2) {
        return usage();
    }
    const char* cmd = ((const char**)(args).data)[1];
    const char* target = "";
    bool have_target = false;
    bool release = false;
    bool force = false;
    bool rest_mode = false;
    const char* backend = "auto";
    bool backend_next = false;
    Array prog_args = ({ Array _a = arr_make(sizeof(const char*)); _a; });
    for (int64_t i = 2; i < args.len; i++) {
        const char* a = ((const char**)(args).data)[i];
        if (rest_mode) {
            ({ const char* _e = a; arr_push(&(prog_args), &_e); });
        } else 
        if (backend_next) {
            backend = a;
            backend_next = false;
        } else 
        if (str_eq(a, "--")) {
            rest_mode = true;
        } else 
        if (str_eq(a, "--backend")) {
            backend_next = true;
        } else 
        if (str_eq(a, "--release")) {
            release = true;
        } else 
        if (str_eq(a, "--force")) {
            force = true;
        } else 
        if (!have_target) {
            target = a;
            have_target = true;
        } else {
            ({ const char* _e = a; arr_push(&(prog_args), &_e); });
        }
    }
    const char* libdir = resolve_libdir(((const char**)(args).data)[0]);
    if (backend_next || (((!str_eq(backend, "auto")) && (!str_eq(backend, "native"))) && (!str_eq(backend, "c")))) {
        printf("%s\n", "error: --backend takes native, c or auto");
        return 2;
    }
    if (str_eq(cmd, "new")) {
        if (!have_target) {
            printf("%s\n", "usage: stratac new <name>");
            return 2;
        }
        return cmd_new(target);
    }
    if (str_eq(cmd, "object")) {
        if (!have_target) {
            printf("%s\n", "usage: stratac object <file.strata> [out.o]");
            return 2;
        }
        const char* out = "";
        if (prog_args.len > 0) {
            out = ((const char**)(prog_args).data)[0];
        }
        return cmd_object(target, out);
    }
    if (str_eq(cmd, "assemble")) {
        if (!have_target) {
            printf("%s\n", "usage: stratac assemble <file.s> [out.o]");
            return 2;
        }
        const char* out = "";
        if (prog_args.len > 0) {
            out = ((const char**)(prog_args).data)[0];
        }
        return cmd_assemble(target, out);
    }
    if (str_eq(cmd, "tokens") || str_eq(cmd, "ast")) {
        if (!have_target) {
            return usage();
        }
        if (str_eq(cmd, "tokens")) {
            return cmd_tokens(target);
        }
        return cmd_ast(target);
    }
    if ((((((!str_eq(cmd, "check")) && (!str_eq(cmd, "emit"))) && (!str_eq(cmd, "asm"))) && (!str_eq(cmd, "ir"))) && (!str_eq(cmd, "build"))) && (!str_eq(cmd, "run"))) {
        return usage();
    }
    Target t = resolve_target(target);
    if (!t.ok) {
        return 1;
    }
    if (str_eq(cmd, "check")) {
        return cmd_check(t.file);
    }
    if (str_eq(cmd, "emit")) {
        return cmd_emit(t.file);
    }
    if (str_eq(cmd, "asm")) {
        return cmd_native(t.file, false, release);
    }
    if (str_eq(cmd, "ir")) {
        return cmd_native(t.file, true, release);
    }
    if (str_eq(cmd, "build")) {
        return cmd_build(t, libdir, release, force, backend);
    }
    return cmd_run(t, libdir, release, force, backend, prog_args);
}

int main(int strata_argc_, char** strata_argv_) {
    strata_set_args(strata_argc_, strata_argv_);
    exit(dmm_main(strata_args()));
    return 0;
}
